class FakeStorage:
    """In-memory FileStorage double (protocol per app/libs/trade_models/storage.py).
    Never touches the real filesystem -- keeps a dict of storage_key -> bytes."""

    def __init__(self) -> None:
        self._files: dict[str, bytes] = {}
        self.save_calls: list[str] = []
        self.open_calls: list[str] = []

    def save(
        self,
        stream: BinaryIO,
        *,
        suggested_name: str,
        content_type: str | None = None,
        subdir: str | None = None,
    ) -> str:
        # BE-4 (014): mirrors LocalStorage's own subdir-prefixing so
        # save_calls entries reflect the real key shape (e.g.
        # "client_kyc_docs/<slug>_<uid8>/fake-<hex>-<name>").
        key_body = f"fake-{uuid.uuid4().hex}-{suggested_name}"
        key = f"{subdir}/{key_body}" if subdir else key_body
        self._files[key] = stream.read()
        self.save_calls.append(key)
        return key

    def open(self, storage_key: str) -> BinaryIO:
        self.open_calls.append(storage_key)
        return io.BytesIO(self._files[storage_key])


