def make_admin(
    session, role: AdminRole, *, name: str | None = "Some Admin", firebase_uid: str | None = None
) -> User:
    """Seeds a Portal.ADMIN user + AdminProfile(role=role). `name=None` seeds a
    profile with no display name, for the assigned_rm fallback-chain tests."""
    user = User(
        id=uuid.uuid4(),
        firebase_uid=firebase_uid or f"{role.value.lower()}-uid-{uuid.uuid4()}",
        email=f"{role.value.lower()}-{uuid.uuid4().hex[:6]}@example.com",
        portal=Portal.ADMIN,
        status=AccountStatus.ACTIVE,
    )
    session.add(user)
    session.flush()
    session.add(AdminProfile(user_id=user.id, role=role, name=name))
    session.commit()
    # BE-2: load admin_profile onto the instance now, in case a caller closes
    # `session` before use in app.dependency_overrides -- an already-loaded
    # attribute is never lazy-loaded on the detached instance.
    session.refresh(user, attribute_names=["admin_profile"])
    return user


def make_client(session, *, assigned_rm_uid: str | None = None, name: str = "Cathy Client") -> User:
    """Seeds a Portal.CLIENT user + ClientProfile -- the target of an
    onboarding cycle. Mirrors the shape ClientRepository.create_with_profile
    produces (status defaults to DISABLED, matching the real onboard path)."""
    user = User(
        id=uuid.uuid4(),
        firebase_uid=f"client-uid-{uuid.uuid4()}",
        email=f"{name.lower().replace(' ', '.')}@example.com",
        portal=Portal.CLIENT,
        status=AccountStatus.DISABLED,
    )
    session.add(user)
    session.flush()
    session.add(
        ClientProfile(
            user_id=user.id,
            name=name,
            assigned_rm_uid=assigned_rm_uid,
            primary_phone="1",
            address="A",
            country_of_residence="HK",
        )
    )
    session.commit()
    return user


def make_ib(prefix: str = "U") -> str:
    """A globally-unique, format-valid client IB account string (letter U +
    7 alphanumerics -- see client_ib_accounts.check).

    client_ib_accounts is the single home of a client's per-model IB account
    and account strings are globally unique, so `client_ib_accounts.ensure`
    raises 409 if two different (client, model) pairs are handed the same
    literal. Every fixture that needs an account therefore mints a fresh one
    instead of reusing a hardcoded literal."""
    return f"{prefix}{uuid.uuid4().hex[:7].upper()}"


