def make_start_req(model: Model, *, email: str | None = None, **overrides) -> StartOnboardingReq:
    email = email or f"client-{uuid.uuid4().hex[:8]}@example.com"
    fields = dict(
        client_name="Cathy Client",
        email=email,
        primary_phone="+852-1234-5678",
        address="1 Main St",
        country_of_residence="Hong Kong",
        id_type="Passport",
        id_number="P1234567",
        client_ib=make_ib(),
        sw_account="SW-0001",
        model_id=model.id,
        units=Decimal("5"),
        mgmt_fee=model.mgmt_fee,
        incentive_fee=model.incentive_fee,
    )
    fields.update(overrides)
    # NEW (014 BE-8): default to exactly the AUM floor for whatever units/model_size
    # ends up in `fields` after overrides, unless the caller explicitly overrode it
    # (e.g. to test the floor boundary itself).
    if "initial_cash_deposit" not in overrides:
        fields["initial_cash_deposit"] = fields["units"] * (model.model_size or Decimal("0"))
    return StartOnboardingReq(**fields)


def run_to_reviewing(
    svc: OnboardingService, model: Model, *, rm_uid: str, settings=None, **req_overrides
):
    """RM-side happy path: start -> upload all 7 REQUIRED_DOCS -> submit.
    Returns the `submit()` result OnboardingDTO. Settings default to the
    firebase-auth-disabled dev bypass so no real Firebase call is ever made."""
    from app.core.config import Settings

    settings = settings or Settings(firebase_auth_disabled=True)
    req = make_start_req(model, **req_overrides)
    started = svc.start(req, caller_uid=rm_uid, identity=FakeIdentityService(), settings=settings)
    for spec in REQUIRED_DOCS:
        svc.upload_document(
            started.id,
            spec.key,
            stream=io.BytesIO(b"fake file bytes"),
            filename=f"{spec.key}.pdf",
            content_type="application/pdf",
            caller_uid=rm_uid,
        )
    return svc.submit(started.id)


def run_full_approved_cycle(
    svc: OnboardingService, model: Model, *, rm_uid: str, compliance_uid: str, **req_overrides
):
    """Full happy path through to an active cycle: start -> upload x7 -> submit
    -> verdict(valid) x7 -> approve. Returns the approved OnboardingDTO.

    Pre-019 signature: `svc.approve(id, compliance_uid=...)`. BE-20 (proposal 019)
    adds required `identity`/`settings` kwargs to `approve` -- this helper is left
    untouched (per the task's "never remove/overwrite existing fixtures" rule) so
    it keeps serving pre-019 test files unmodified; it will raise TypeError once
    BE-20 lands, which is expected and is why BE-20's own test file below defines
    its own local cycle-building helper instead of reusing this one."""
    submitted = run_to_reviewing(svc, model, rm_uid=rm_uid, **req_overrides)
    for spec in REQUIRED_DOCS:
        svc.verdict(
            submitted.id, spec.key, VerdictReq(verdict="valid"), reviewer_uid=compliance_uid
        )
    return svc.approve(submitted.id, compliance_uid=compliance_uid)


