class FakeIdentityServiceWithSetPasswordLink(FakeIdentityService):
    """BE-13 renames `generate_invite_link` -> `generate_set_password_link` on
    the real `FirebaseIdentityService`. The base `FakeIdentityService` above
    (proposal 004's own double) predates that rename and only has the old name,
    so this small subclass adds the new one without touching proposal 004's
    test double. Not yet present on the real service -- BE-20's own test file
    calls `identity.generate_set_password_link(...)`, which is exactly the
    not-yet-implemented seam it's meant to exercise."""

    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)
        self.generate_set_password_link_calls: list[str] = []

    def generate_set_password_link(self, email: str) -> str:
        self.generate_set_password_link_calls.append(email)
        return f"https://fake.invalid/set-password?email={email}"
